USE db_ventas;
CREATE TABLE IF NOT EXISTS sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_request_id VARCHAR(100) NOT NULL UNIQUE, total DECIMAL(12,2) NOT NULL DEFAULT 0, status ENUM('pending','completed','failed') NOT NULL DEFAULT 'pending', created_by BIGINT UNSIGNED, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sale_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sale_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, product_name VARCHAR(180) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(12,2) NOT NULL, FOREIGN KEY (sale_id) REFERENCES sales(id)) ENGINE=InnoDB;
